// 1. Webhook Security Verification
const headers = $input.item.json.headers || {};
const expectedApiKey = $env.BOOKLEAF_WEBHOOK_SECRET || 'bookleaf_secure_token_2026';
const receivedKey = headers['x-bookleaf-api-key'] || $input.item.json.query?.apiKey || $input.item.json.body?.apiKey;

if (receivedKey !== expectedApiKey) {
  throw new Error('Unauthorized: Invalid or missing x-bookleaf-api-key header.');
}

const body = $input.item.json.body || {};
const authorId = body.author_id || body.authorId;

if (!authorId && !body.author) {
  throw new Error('Bad Request: author_id or author object is required in webhook payload.');
}

// 2. Idempotency Check (Prevent duplicate clicks within 60 seconds)
const requestId = body.request_id || `req_${authorId}_${Date.now()}`;

return {
  json: {
    authenticated: true,
    author_id: authorId,
    requestId: requestId,
    timestamp: new Date().toISOString(),
    payload: body
  }
};

// 3. Process Author & Book Data
const payload = $input.item.json.payload;
let author = payload.author || {};
let books = payload.books || [];

// If Bubble passed flattened data:
if (!author.name && payload.name) {
  author = {
    author_id: payload.author_id,
    name: payload.name,
    email: payload.email,
    city: payload.city,
    phone: payload.phone,
    joined_date: payload.joined_date
  };
}

// Calculate consolidated totals
let totalEarned = 0;
let totalPaid = 0;
let totalPending = 0;
let totalCopies = 0;
const publishedBooks = [];
const inProductionBooks = [];

books.forEach(b => {
  const isProduction = (b.status || '').toLowerCase().includes('in production');
  if (isProduction) {
    inProductionBooks.push({
      title: b.title,
      genre: b.genre || 'General',
      status: b.status
    });
  } else {
    const earned = Number(b.total_royalty_earned || b.totalRoyaltyEarned || 0);
    const paid = Number(b.royalty_paid || b.royaltyPaid || 0);
    const pending = Number(b.royalty_pending || b.royaltyPending || (earned - paid));
    const copies = Number(b.total_copies_sold || b.totalCopiesSold || 0);

    totalEarned += earned;
    totalPaid += paid;
    totalPending += pending;
    totalCopies += copies;

    publishedBooks.push({
      book_id: b.book_id || b.bookId,
      title: b.title,
      isbn: b.isbn,
      mrp: b.mrp,
      status: b.status,
      copies_sold: copies,
      royalty_earned: earned,
      royalty_paid: paid,
      royalty_pending: pending,
      last_payout_date: b.last_royalty_payout_date || b.lastPayoutDate || 'None'
    });
  }
});

return {
  json: {
    author_id: author.author_id || $input.item.json.author_id,
    author_name: author.name || 'Author',
    author_email: author.email || '',
    author_city: author.city || '',
    total_earned: totalEarned,
    total_paid: totalPaid,
    total_pending: totalPending,
    total_copies_sold: totalCopies,
    published_books: publishedBooks,
    in_production_books: inProductionBooks,
    has_pending: totalPending > 0,
    is_below_minimum_threshold: totalPending > 0 && totalPending < 1000,
    requestId: $input.item.json.requestId
  }
};

// 4. Construct Grounded Prompt for AI API
const data = $input.item.json;

const systemPrompt = `You are the Author Relations & Royalty Specialist at BookLeaf Publishing (a leading self-publishing house in India & US).
Your goal is to compose an empathetic, transparent, highly accurate, and professional royalty summary email to an author.

BookLeaf Royalty Policies to Ground Your Response:
1. Royalty Split: 80% of net profit goes to author, 20% to BookLeaf.
2. Payout Schedule: Royalties are calculated quarterly and disbursed within 45 days of the quarter ending via bank transfer.
3. Minimum Payout Threshold: ₹1,000. If accumulated royalties are below ₹1,000, they roll over to the next quarter.
4. If royalties are fully paid up (₹0 pending), warmly celebrate their performance and congratulate them.
5. If royalties are overdue or pending, provide a clear timeline for the upcoming quarterly payout cycle without corporate deflection.
6. If any titles are still In Production (Cover Design / Typesetting), provide an encouraging status update.
7. Tone: Empathetic, supportive, professional. Authors are creative partners, not customers to manage.
8. Output Format: Return a JSON object with two fields: "subject" and "html_body". Do NOT wrap in markdown code blocks.`;

let booksText = data.published_books.map((b, idx) => 
  `${idx + 1}. "${b.title}" (ISBN: ${b.isbn})
   - Status: ${b.status} | MRP: ₹${b.mrp}
   - Copies Sold: ${b.copies_sold} copies
   - Royalty Earned: ₹${b.royalty_earned} | Royalty Paid: ₹${b.royalty_paid}
   - Royalty Pending: ₹${b.royalty_pending} (Last payout: ${b.last_payout_date})`
).join('\n\n');

if (data.published_books.length === 0) {
  booksText = "No published titles yet.";
}

let productionText = "";
if (data.in_production_books.length > 0) {
  productionText = "\nTitles in Production:\n" + data.in_production_books.map(b => `- "${b.title}" (Stage: ${b.status})`).join('\n');
}

const userPrompt = `Generate a royalty summary notification for:
Author Name: ${data.author_name}
City: ${data.author_city}
Total Royalty Earned: ₹${data.total_earned}
Total Royalty Paid: ₹${data.total_paid}
Total Royalty Pending: ₹${data.total_pending}
Total Copies Sold: ${data.total_copies_sold}
Below Threshold (<₹1,000): ${data.is_below_minimum_threshold ? "YES (will roll over to next quarter)" : "NO"}

Published Books Breakdown:
${booksText}
${productionText}

Please write the complete personalized email now.`;

return {
  json: {
    ...data,
    systemPrompt,
    userPrompt
  }
};

