// 5. Parse AI Response with Fallback Heuristics
const item = $input.item.json;
const priorData = $('Data Aggregator & Rules Engine').first().json;

let subject = `BookLeaf Royalty Update - ${priorData.author_name}`;
let htmlBody = "";
let aiStatus = "Success";

if (item.error || !item.choices || !item.choices[0]) {
  aiStatus = "Fallback_Generated";
  subject = `BookLeaf Royalty Summary & Status Report for ${priorData.author_name}`;

  const pendingNote = priorData.total_pending > 0
    ? (priorData.is_below_minimum_threshold 
        ? `<p>Your pending balance of ₹${priorData.total_pending} is currently below the ₹1,000 minimum threshold and will roll over to the next quarter.</p>`
        : `<p>Your pending balance of ₹${priorData.total_pending} will be processed in the upcoming quarterly cycle within 45 days of the quarter ending.</p>`)
    : `<p>Your royalty accounts are fully settled with zero pending balance. Thank you for being a valued BookLeaf author!</p>`;

  htmlBody = `
    <div style="font-family: Arial, sans-serif; line-height: 1.6; color: #333;">
      <h2 style="color: #059669;">Hello ${priorData.author_name},</h2>
      <p>Here is your latest royalty overview across your titles at BookLeaf Publishing:</p>
      <table style="width: 100%; border-collapse: collapse; margin: 15px 0;">
        <tr style="background: #f3f4f6;">
          <th style="padding: 8px; border: 1px solid #ddd;">Total Copies Sold</th>
          <th style="padding: 8px; border: 1px solid #ddd;">Total Earned</th>
          <th style="padding: 8px; border: 1px solid #ddd;">Total Paid</th>
          <th style="padding: 8px; border: 1px solid #ddd;">Pending Balance</th>
        </tr>
        <tr style="text-align: center;">
          <td style="padding: 8px; border: 1px solid #ddd;">${priorData.total_copies_sold}</td>
          <td style="padding: 8px; border: 1px solid #ddd;">₹${priorData.total_earned}</td>
          <td style="padding: 8px; border: 1px solid #ddd;">₹${priorData.total_paid}</td>
          <td style="padding: 8px; border: 1px solid #ddd; font-weight: bold; color: #059669;">₹${priorData.total_pending}</td>
        </tr>
      </table>
      ${pendingNote}
      <p>Best regards,<br><strong>BookLeaf Publishing Operations Team</strong></p>
    </div>
  `;
} else {
  try {
    const parsed = JSON.parse(item.choices[0].message.content);
    subject = parsed.subject || subject;
    htmlBody = parsed.html_body || parsed.body || item.choices[0].message.content;
  } catch (e) {
    htmlBody = item.choices[0].message.content;
  }
}

return {
  json: {
    author_id: priorData.author_id,
    author_name: priorData.author_name,
    author_email: priorData.author_email,
    total_pending: priorData.total_pending,
    email_subject: subject,
    email_body: htmlBody,
    status: "Success",
    ai_status: aiStatus,
    timestamp: new Date().toISOString()
  }
};

